-- 202: Original BrillaPrep WASSCE BrillaPrep transitional Basketry beta content blueprint questions, part 10.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_202_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_202_guard;
INSERT INTO _migration_202_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_037' AND NOT (q.topic_id IS 'topic_was_basketry_b004_8' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should a loose rim binding be repaired before the basket is used again?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Continued handling can release stakes and enlarge the structural failure","B. Add a fresh decorative binding over the loose course while leaving its failed ends unsecured","C. Trim the projecting fibres flush and rely on the remaining border until the next full maintenance","D. Moisten and retighten the visible wrap without checking whether hidden binding ends have broken"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The rim restrains stake ends and receives frequent handling, so early repair restores confinement before repeated movement damages adjacent weaving or creates sharp exposed elements. Therefore the correct answer is A: Continued handling can release stakes and enlarge the structural failure.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_8' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_037' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_202_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_038' AND NOT (q.topic_id IS 'topic_was_basketry_b004_8' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which harvesting practice best supports a renewable supply of basketry cane?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Return each season to the most accessible patch and take only its straightest mature stems","B. Cut mature stems selectively while protecting regrowth and the habitat","C. Retain the oldest declining stems permanently and harvest the vigorous mature stems around them","D. Rotate between clumps while taking most market-size stems and soft young shoots from the selected clump"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Selective harvesting retains regenerative capacity and habitat conditions, allowing future stems to mature while reducing erosion and resource depletion associated with complete clearance. Therefore the correct answer is B: Cut mature stems selectively while protecting regrowth and the habitat.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_038' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_202_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_039' AND NOT (q.topic_id IS 'topic_was_basketry_b004_8' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the best use of clean short offcuts that cannot serve as full-length weavers?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Combine all clean offcuts into mixed bundles for decoration without grading them by stiffness or length","B. Join short offcuts end to end with concealed overlaps so they can replace continuous structural weavers","C. Sort them for samples, small bindings, decoration or other suitable components","D. Reserve the offcuts for future repairs without separating them by species, moisture condition or size"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Sorting by length, condition and material lets safe offcuts substitute for new stock in appropriately small tasks, reducing waste without placing unsuitable pieces in critical structural positions. Therefore the correct answer is C: Sort them for samples, small bindings, decoration or other suitable components.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_039' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_202_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_040' AND NOT (q.topic_id IS 'topic_was_basketry_b004_8' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How should a newly completed carrying basket be checked for fitness for purpose?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Hang the intended load from the handle once and record only whether the attachment remains intact","B. Press the base, walls and handle separately by hand instead of testing the assembled load path","C. Apply a controlled representative load while observing the base, sides and handle attachments","D. Inspect symmetry and weave tightness while empty, then infer capacity from the stated cane grade"]' AND q.correct_answer IS 'C' AND q.explanation IS 'A controlled service-relevant test verifies that the complete load path performs without excessive distortion or loosening, while avoiding the damage and poor evidence produced by uncontrolled overloading. Therefore the correct answer is C: Apply a controlled representative load while observing the base, sides and handle attachments.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_8' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_040' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_037', 'topic_was_basketry_b004_8', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Why should a loose rim binding be repaired before the basket is used again?', 'multiple_choice', NULL, '["A. Continued handling can release stakes and enlarge the structural failure","B. Add a fresh decorative binding over the loose course while leaving its failed ends unsecured","C. Trim the projecting fibres flush and rely on the remaining border until the next full maintenance","D. Moisten and retighten the visible wrap without checking whether hidden binding ends have broken"]', 'A', 'The rim restrains stake ends and receives frequent handling, so early repair restores confinement before repeated movement damages adjacent weaving or creates sharp exposed elements. Therefore the correct answer is A: Continued handling can release stakes and enlarge the structural failure.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_8', 'Explain', 'AO1', NULL, NULL, 'board_waec');
